head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > visibleSecList]<br/>Calendar 컴포넌트의 초 SelectBox 에 표시할 초 항목 아이템을 설정합니다.",
    "validation" : [
        "콤마(',') 로 구분된 초 값을 문자열로 설정합니다.",
        "',' 로 구분한 갯수에 관계없이 설정값은 모두 초 영역 SelectBox 의 아이템으로 설정됩니다.",
        "값을 설정하지 않으면 '0,1,...,58,59' 의 60개 값이 설정됩니다.",
        "calendarValueType='yearMonthDateTimeSec' 인 경우에 동작합니다.",
        "displayHrMinSec=true 이면 visibleSecList 속성의 각 값에 단위('초') 가 결합되어 표시됩니다.",
        "gotoTime() 메소드로 시간을 설정할 때, visibleSecList 속성이 설정되어 있으면 문자열 그대로 처리됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        visibleSecList : con_visibleSecList.getText(),
        calendarValueType : con_calendarValueType.getText(),
        displayHrMinSec : con_displayHrMinSec.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="visibleSecList 설정 후 초 SelectBox 아이템 목록 및 gotoTime() 동작 확인"', '', 'label1');
    await $c.gcm.createBasicCalendar(cList, eList);

    // 초기 선택일 설정 (calendarValueType='yearMonthDateTimeSec' 14자리)
    let cvt = target1.options.calendarValueType;
    let initVal = ({
        'yearMonthDate'       : '20250518',
        'yearMonth'           : '202505',
        'yearMonthDateHour'   : '2025051812',
        'yearMonthDateTime'   : '202505181234',
        'yearMonthDateTimeSec': '20250518123456'
    })[cvt] || '20250518123456';
    target1.gotoCalendar(initVal);
}



// calendar 클릭 시 초 SelectBox 아이템 목록 자동 출력
// validation:
//  - 초 SelectBox 아이템 목록이 visibleSecList 설정대로 구성됨
//  - 미설정 시 '0,1,...,58,59' 60개 자동 설정
//  - displayHrMinSec=true 이면 각 값에 '초' 단위가 결합되어 표시됨
//  - calendarValueType='yearMonthDateTimeSec' 인 경우에만 초 SelectBox 가 존재함
scwin.target1_onclick = function (e) {
    setTimeout(function () {
        // validation: 초 SelectBox 아이템 목록 (DOM 직접 조회, displayHrMinSec=true 이면 '초' 단위 결합)
        let labels = [];
        let itemTable = document.querySelector('[id$="target1_selectbox_second_itemTable"]');
        if (itemTable) {
            let rows = itemTable.querySelectorAll('.w2table_sb_row');
            rows.forEach(function (row) {
                let t = row.textContent.trim();
                if (t) labels.push(t);
            });
            // fallback: w2table_sb_row 미매칭 시 [id*="_item_"] 사용
            if (labels.length === 0) {
                let items = itemTable.querySelectorAll('[id*="_item_"]');
                items.forEach(function (it) {
                    let t = it.textContent.trim();
                    if (t) labels.push(t);
                });
            }
        }
        wf_body_bottom.getObj("scwin").setReturnValue("[초 SelectBox 아이템 개수] " + labels.length);
        wf_body_bottom.getObj("scwin").setReturnValue("[초 SelectBox 아이템 목록] '" + labels.join(',') + "'");
    }, 500);
};



// [gotoTime 호출] 버튼
// validation:
//  - gotoTime() 메소드로 시간을 설정할 때, visibleSecList 속성이 설정되어 있으면 문자열 그대로 처리
scwin.btn_gotoTime_onclick = function (e) {
    let beforeVal = target1.getValue();
    let secArg = par_gotoTime_sec.getValue();
    target1.gotoTime(12, 34, secArg);
    let afterVal = target1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("[gotoTime(12,34,'" + secArg + "') 호출] 전='" + beforeVal
        + "' / 후='" + afterVal + "' (visibleSecList 설정 시 문자열 그대로 처리)");
};
